describe('Homepage Hero Section - Mobile Responsiveness', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display mobile-optimized hero section on small screens', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-title"]').should('contain', 'Welcome to our site');
    cy.get('[data-testid="hero-subtitle"]').should('contain', 'Discover amazing products');
    cy.get('[data-testid="hero-cta-button"]').should('be.visible');
    cy.get('[data-testid="hero-cta-button"]').should('contain', 'Shop Now');
    cy.get('[data-testid="hero-image"]').should('be.visible');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'src');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'srcset');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'srcset_by');
  });

  it('should handle mobile hero section with different content and layout', () => {
    cy.viewport('iphone-12');
    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-title"]').should('have.length', 1);
    cy.get('[data-testid="hero-subtitle"]').should('have.length', 1);
    cy.get('[data-testid="hero-cta-button"]').should('be.visible');
    cy.get('[data-testid="hero-cta-button"]').should('have.length', 1);
    cy.get('[data-testid="hero-image"]').should('be.visible');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'srcset');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'srcset_by');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'srcset_sizes');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'srcset_sizes');
  });
});
